/**
 * THE PARITY PROOF for bot push grants (`docs/security/private-repos.md` §24): every `bot_push__*`
 * vector in `forge-contracts/vectors/` (generated by `tools/private-repos-vectors/push.py`), run
 * against `./push-grant`, the access notice's push fields (`lib/private/access-notice.ts`) and the
 * ref update validity check (`./resolveRef`). forge-core `rules::push_grant::tests::bot_push_vectors`
 * runs the same files with the same input and output shapes.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { allowsPush, decodeNotice, pushEntries, pushPolicy } from '../private/access-notice'
import { bytesToHex, hexToBytes } from '../private/bytes'
import { mark, pick, prefixOf, untilFor, usable, type GrantContext, type PushGrant, type PushTarget } from './push-grant'
import { isUpdateValid } from './resolveRef'
import type { RefUpdate } from './types'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('bot_push__') && f.endsWith('.json'))
  .sort()

const obj = (j: Json | undefined): Obj => j as Obj
const arr = (j: Json | undefined): Json[] => j as Json[]

function grantOf(j: Json | undefined): PushGrant {
  const o = obj(j)
  return {
    id: o.id as string,
    granter: o.granter as string,
    bot: o.bot as string,
    ...(typeof o.prefix === 'string' ? { prefix: o.prefix } : {}),
    ...(typeof o.scope === 'string' ? { scope: o.scope } : {}),
    until: o.until as number,
    createdAt: o.createdAt as number,
  }
}

function ctxOf(j: Json | undefined): GrantContext {
  const o = obj(j)
  return { now: o.now as number, botRowAt: typeof o.botRowAt === 'number' ? o.botRowAt : null, maintainers: new Set(arr(o.maintainers) as string[]) }
}

function run(i: Obj): Json {
  switch (i.op) {
    case 'grantUsable':
      return { results: arr(i.cases).map((c) => ({ name: obj(c).name as Json, unusable: usable(grantOf(obj(c).grant), ctxOf(obj(c).ctx)) })) }
    case 'grantPick': {
      const grants = arr(i.grants).map(grantOf)
      const ctx = ctxOf(i.ctx)
      return {
        results: arr(i.targets).map((t) => {
          const tt = obj(obj(t).target)
          const target: PushTarget = typeof tt.public === 'string' ? { public: tt.public } : { exact: tt.exact as string }
          const got = pick(grants, target, ctx)
          const p: Json = 'grant' in got ? { grant: got.grant.id } : got.reason === 'notCovered' ? { reason: 'notCovered' } : { reason: 'unusable', why: got.why }
          return { name: obj(t).name as Json, pick: p }
        }),
      }
    }
    case 'prefixOf':
      return {
        results: arr(i.patterns).map((p): Json => {
          const got = prefixOf(p as string)
          return 'prefix' in got ? { pattern: p, prefix: got.prefix } : { pattern: p, refused: got.refused }
        }),
      }
    case 'untilFor':
      return {
        results: arr(i.requested).map((r): Json => {
          const got = untilFor(i.now as number, typeof r === 'number' ? r : null)
          return 'until' in got ? { until: got.until } : { refused: got.refused }
        }),
      }
    case 'pushMark':
      return {
        results: arr(i.cases).map((c) => {
          const o = obj(c)
          const m = mark(o.at as number, o.grant === null ? null : grantOf(o.grant), typeof o.botRowAt === 'number' ? o.botRowAt : null, typeof o.noticeAllowsPush === 'boolean' ? o.noticeAllowsPush : null)
          return { name: o.name as Json, mark: m }
        }),
      }
    case 'noticePush':
      return {
        results: arr(i.notices).map((n) => {
          const notice = decodeNotice(hexToBytes(obj(n).plaintextHex as string))
          if (notice === null) throw new Error(`${String(obj(n).name)}: the notice must decode`)
          const entries = pushEntries(notice)
          return {
            name: obj(n).name as Json,
            entries: entries === null ? null : entries.map((e): Json => ('prefix' in e.target ? { grant: bytesToHex(e.grant), prefix: e.target.prefix } : { grant: bytesToHex(e.grant), members: bytesToHex(e.target.members) })),
            policy: { ...pushPolicy(notice) },
            allowsPush: allowsPush(notice),
          }
        }),
      }
    case 'refValid':
      return { results: arr(i.updates).map((u) => isUpdateValid(u as unknown as RefUpdate, [])) }
    default:
      throw new Error(`unknown op ${String(i.op)}`)
  }
}

describe('bot push conformance vectors', () => {
  it('finds them', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(7)
  })
  for (const f of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector
    it(v.name, () => {
      expect(run(v.input)).toEqual(v.expected)
    })
  }
})
